interface.definition:
a!localVariables(
  local!isOldVersion:if(
    a!isNullOrEmpty(ri!ask.createdOn),
    false,
    if(
      todatetime(ri!ask.createdOn)<#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false)
  ),
  local!isRequestAfterV4:if(
    a!isNullOrEmpty(ri!ask.createdOn),
    true,
    if(
      todatetime(ri!ask.createdOn) > #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      false
    )
  ),
  local!selectedTab: 1,
  local!isComplete,
  local!nmpGroup,
  local!loggedInUserDetail: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3070432"(
    userName: loggedInUser()
  ).data,
  local!isUserDppOps: isusermemberofgroups(
    loggedInUser(),
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"
  ),
  local!region: if(
    toboolean(local!isOldVersion) = true,
    if(
      ri!ask.regionId = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206289",
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206267"[1],
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206267"[2]
    ),
    #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11605098"
  ),
  local!bUs: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084520"(
    regionId: ri!ask.regionId,
    isActive: true,
    columns: {
      "buId",
      "regionId",
      "bu"
    }
  ).data,
  local!nextStatusId: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3277295"(
    taskStatusId: ri!task.statusId,
    isComplete: local!isComplete,
    selectedLeadershipGroup: ri!selectedApprover,
    isEdit: ri!isEdit,
    selectedNMPGroup: local!nmpGroup
  ),
  local!nextAssigneeGroup: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6875393"(
    taskStatusId: local!nextStatusId,
    regionId: ri!ask.regionId,
    oldVersion: local!isOldVersion
  ),
  local!assignee: if(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!nextAssigneeGroup),
    null,
    a!groupMembers(local!nextAssigneeGroup)
  ),
  local!selectedGroupName: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3374322"(
    selectedGroup: ri!selectedApprover
  ),
  local!assigneeId: if(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(index(local!assignee,"totalCount",null)),
    null,
    if(
      local!assignee.totalCount > 1,
      if(toboolean(local!isOldVersion)=true,
      property(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
          description: if(
            #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!selectedGroupName),
            #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3374322"(local!nextAssigneeGroup),
            local!selectedGroupName
          ),
          refTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177789"
        ).data,
        "refId",
        null
      ),
      property(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
          description: if(
            #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!selectedGroupName),
            #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3374322"(local!nextAssigneeGroup),
            local!selectedGroupName
          ),
          refTypeId: #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11818616"
        ).data,
        "refId",
        null
      )),
      property(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3070432"(
          userName: if(
            or(
              #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!assignee.data),
              local!assignee.totalCount = 0
            ),
            -1,
            tostring(property(local!assignee,"data",null))
          )
        ).data,
        "userId",
        null
      )
    )
  ),
  local!fullName: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(loggedInUser()),
  local!dppOPSReviewAssignee: a!groupMembers(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"),
  local!dppOPSReviewassigneeId: #"_a-0000e7e4-4b4e-8000-9c1d-011c48011c48_6307911",
  local!DPPApproversList: #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(
    reject(
    fn!isnull,
    #"SYSTEM_SYSRULES_forEach"(
      items: if(toboolean(local!isOldVersion)=true,
      remove(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3240923",{10,11,12,13,14,15,16,17}),
      remove(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3240923",{2,3,1,6,7,8,12,13,14})
      ),
      expression: if(
        tointeger(a!groupMembers(fv!item).totalCount) <> 0,
        fv!item,
        null
      )
    )
  )),
  local!previousComment: a!refreshVariable(
    value: index(ri!comment, "comment",null),
    refreshOnReferencedVarChange: false
  ),
  #"SYSTEM_SYSRULES_formLayout_v1"(
    label: if(toboolean(local!isOldVersion)=true,
    "Rotational ASK Form: " & local!region & " " & ri!ask.fYear,
    "Rotational ASK Form: " & ri!ask.askName /*& " " & ri!ask.fYear*/
    ),
    contents: {
      /*ALL TABS*/
      #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3769972"(
        selectedTab: local!selectedTab,
        showWhen: true,
        previousCommentsShowWhen: true,
        isReview: true
      ),
      /*DETAILS*/
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        label: "Details",
        contents: {
          #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3341961"(
            task: ri!task
          ),
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns:
            {
              #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_textField"(
                label: "Name of the ASK",
                value: ri!ask.askName,
                saveInto: ri!ask.askName,
                characterLimit: 100,
                showWhen: if(
                  toboolean(local!isOldVersion) = true,
                  false,
                  true
                ),

                readOnly: true

              )

            },
            width: "MEDIUM"
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_textField"(
                label: "Fiscal Year of ASK",
                value: ri!ask.fYear,
                saveInto: ri!ask.fYear,
                showWhen: if(
                  toboolean(local!isOldVersion) = true,
                  false,
                  true
                ),
                readOnly: true

              )

            },
            width: "MEDIUM",

          ),
          }),
          /*BU SUMMARY*/
          #"SYSTEM_SYSRULES_boxLayout"(
            label: if(
              toboolean(local!isOldVersion) = true,
              local!region & " Region",
              ""
            ),
            contents: {#"SYSTEM_SYSRULES_gridLayout"(
            headerCells: {
              #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "BU", align: "CENTER" ),
              #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Plan" , align: "CENTER")
            },
            rows: {
              #"SYSTEM_SYSRULES_forEach"(
                items: ri!rotationalAskDetails,
                expression: #"SYSTEM_SYSRULES_gridRowLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_textField"(
                      label: "",
                      value: property(
                        index(
                          local!bUs,
                          wherecontains(
                            tointeger(fv!item.buId),
                            tointeger(property(local!bUs,"buId",null))
                          ),
                          {}
                        ),
                        "bu",
                        null
                      ),
                      readOnly: true,
                      align: "CENTER"
                    ),
                    #"SYSTEM_SYSRULES_integerField"(
                      value: index(fv!item, "plan",tointeger({})),
                      saveInto: fv!item.plan,
                      readOnly: true,
                      align: "CENTER"
                    )

                  }
                )
              ),
              #"SYSTEM_SYSRULES_gridRowLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "Total",
                      size: "MEDIUM",
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: sum(
                        #"SYSTEM_SYSRULES_forEach"(
                          items: ri!rotationalAskDetails,
                          expression: index(fv!item,"plan",tointeger(null))
                        )
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                }
              )
            }
            )},
            showWhen: local!selectedTab = 1,
            style: "ACCENT",
            isCollapsible: true,
            isInitiallyCollapsed: false,
            marginBelow: "STANDARD")
        },
        showWhen: local!selectedTab = 1,
        isCollapsible: true,
        divider: "ABOVE",
        dividerWeight: "MEDIUM",
        dividerColor: "ACCENT",
        marginBelow: "STANDARD"
      ),
      /*ADDITIONAL APPROVALS*/
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        label: "Additional Approvals",
        contents: {
          #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3192683"(
            selectedGroup: ri!selectedApprover,
            showWhen: and(
              contains(
                {
                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3179809"[15]
                },
                tostring(ri!taskstatus)
              ),
              local!isUserDppOps,
              local!selectedTab = 1
            ),
            isComplete: local!isComplete,
            nmpGroup: local!nmpGroup,
            DPPApproversList: local!DPPApproversList,
            isSendToNMP: ri!sendToPIC,
            askTypeId: property(ri!ask,"typeId",null)
          )
        },
        showWhen: and(
          contains(
            {
              #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3179809"[15]
            },
            tostring(ri!taskstatus)
          ),
          local!isUserDppOps,
          local!selectedTab = 1
        ),
        isCollapsible: true,
        divider: "ABOVE",
        dividerWeight: "MEDIUM",
        dividerColor: "ACCENT",
        marginBelow: "STANDARD"
      ),
      /*REVIEW COMMENT*/
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        label: "Review Comment",
        contents: {
          #"SYSTEM_SYSRULES_paragraphField"(
            label: "Review Comment",
            labelPosition: "COLLAPSED",
            instructions: "A comment is required when returning rotational ASK form",
            value: index(ri!comment, "comment",null),
            saveInto: ri!comment.comment,
            characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238137",
            required: ri!action=#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155721"
          )
        },
        showWhen: local!selectedTab = 1,
        isCollapsible: true,
        divider: "ABOVE",
        dividerWeight: "MEDIUM",
        dividerColor: "ACCENT",
        marginBelow: "STANDARD"
      ),
      /*ATTACHMENTS TAB*/
      #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3775387"(
        documents: ri!documents,
        showWhen: local!selectedTab = 2
      ),
      /*PREVIOUS Comments*/
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3192543"(
        comments:  ri!previousComments,
        showWhen: local!selectedTab = 3
      ),
      #"SYSTEM_SYSRULES_richTextDisplayField"(
        labelPosition: "COLLAPSED",
        value: {
          #"SYSTEM_SYSRULES_richTextItem_v1"(
            text: {
              "By clicking ""approve"" I certify that I have performed my review in accordance with the DPP System of Quality Controls as outlined in the Resource Management "
            },
            color: "ACCENT",
            size: "MEDIUM",
            style: {
              "EMPHASIS"
            }
          ),
          #"SYSTEM_SYSRULES_richTextItem_v1"(
            text: {
              "Risk and Controls Matrix"
            },
            link: #"SYSTEM_SYSRULES_safeLink"(
              label: "Risk and Controls Matrix",
              uri: #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12517174"[2],
            ),
            color: "ACCENT",
            size: "MEDIUM",
            style: {
              "EMPHASIS",
              "STRONG"
            }
          )
        },
        showWhen: and(
          local!isUserDppOps = false,
          or(
            property(ri!task,"statusId",tointeger(null))=#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[1],
            property(ri!task,"statusId",tointeger(null))=#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[2],
            property(ri!task,"statusId",tointeger(null))=#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[3],
            property(ri!task,"statusId",tointeger(null))=#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[4]
          ),
          local!selectedTab = 1
        ),
        align: "CENTER"
      )
    },
    buttons: #"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3496966"(
      rotationalAskDetails: ri!rotationalAskDetails,
      ask: ri!ask,
      task:ri!task,
      showWhen: local!selectedTab = 1,
      buttonValue: ri!action,
      comment: ri!comment,
      selectedBUs: ri!rotationalAskDetails,
      isEdit: ri!isEdit,
      region: local!region,
      isReview: true,
      auditHistory: ri!auditHistory,
      assigneeId: local!assigneeId,
      nextStatusId: local!nextStatusId,
      assignee:local!assignee,
      dppOPSReviewAssignee:local!dppOPSReviewAssignee,
      dppOPSReviewassigneeId:local!dppOPSReviewassigneeId,
      isComplete: local!isComplete,
      isInitialAmend: false,
      newVersion: null,
      previousComment: local!previousComment,
      fullName: local!fullName,
      loggedInUserDetail: local!loggedInUserDetail,
      commentIDtoDelete: ri!commentIDtoDelete,
      selectedApprover:  ri!selectedApprover
    ),
    validations: {
      #"SYSTEM_SYSRULES_validationMessage"(
        message: "Please Select an Option for an additional approver or mark ASK as complete",
        validateAfter: "SUBMIT",
        showWhen: and(
          /*ri!action = "SUBMIT",*/
          ri!taskStatus = "DPP Ops Review - Final",
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!isComplete),
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!selectedApprover),
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!sendToPIC)
        )
      )
    },
    skipAutoFocus: true
  )
)
